corrected_code:
const { Kafka } = require('kafkajs');
const kafka = new Kafka({ brokers: [process.env.KAFKA_URI] });
const consumer = kafka.consumer({ groupId: 'pharmacy-delivery-scheduler' });

async function listen() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'pharmacy.prescription.reschedule_delivery' });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const event = JSON.parse(message.value.toString());
      const { prescriptionId, newDeliveryAddress, scheduledDate, actorPatientId } = event;

      const prescription = await PrescriptionFulfillment.findOne({
        where: { id: prescriptionId, patientId: actorPatientId }
      });
      if (!prescription) {
        console.warn(`Prescription reschedule rejected: ${prescriptionId} does not belong to patient ${actorPatientId}`);
        return;
      }

      await prescription.update({ deliveryAddress: newDeliveryAddress, scheduledDate });
      console.log(`Prescription ${prescriptionId} rescheduled`);
    }
  });
}
